tool_input.command:
$wt="D:\repository\门户\zhi2-web-admin-wt-chart-font-clarity"
$diff = git -C $wt diff "src/views/property/marketMonitor/assets/dashboard.css"
$lines = $diff -split "`n"
foreach($l in $lines){
  if($l -match 'font-sans|JetBrains|font-mono|font-family'){
    Write-Host $l.Substring(0,[Math]::Min(220,$l.Length))
  }
}

$wt="D:\repository\门户\zhi2-web-admin-wt-chart-font-clarity"
$line = (Get-Content "$wt\src/views/property/marketMonitor/assets/dashboard.css" -Raw -Encoding UTF8)
foreach($p in @('JetBrains','Noto Sans','Plus Jakarta','JetBrains Mono')){
  Write-Host "$p :" ([regex]::Matches($line,$p).Count)
}
# show context of any Noto Sans
$idx = $line.IndexOf("Noto Sans")
if($idx -ge 0){
  $start=[Math]::Max(0,$idx-120); $end=[Math]::Min($line.Length,$idx+120)
  Write-Host "Noto Sans context:" $line.Substring($start,$end-$start)
}

$main="D:\repository\门户\zhi2-web-admin"
$vc=(Get-Content "$main\src\views\property\marketMonitor\components\KpiCards.vue" -Raw -Encoding UTF8)
Write-Host "fontWeight occurrences (any spacing):"
[regex]::Matches($vc,'fontWeight\s*:?\s*\d+') | ForEach-Object { $_.Value }
Write-Host "--- textStyle blocks containing 334155 ---"
[regex]::Matches($vc,'textStyle\s*:\s*\{[^}]*\}') | ForEach-Object { $_.Value }
